136	     4	/** MIME type from magic bytes; only png/jpeg/gif/webp. SVG and everything else → null. */
137	     5	export function sniffImage(b: Uint8Array): string | null {
138	     6	  const ascii = (from: number, to: number) => String.fromCharCode(...b.subarray(from, to));
139	     7	  if (b.length >= 8 && [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a].every((v, i) => b[i] === v)) return 'image/png';
140	     8	  if (b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg';
141	     9	  if (b.length >= 6 && (ascii(0, 6) === 'GIF87a' || ascii(0, 6) === 'GIF89a')) return 'image/gif';
142	    10	  if (b.length >= 12 && ascii(0, 4) === 'RIFF' && ascii(8, 12) === 'WEBP') return 'image/webp';
143	    11	  return null;
144	    12	}
