import { DatabaseSync } from 'node:sqlite';
import fs from 'node:fs';
import path from 'node:path';

// One SQLite file shared by all three PoCs (pocs/.data/super-planer.db) so step1 → workflow-view → plan-doc can hand data over.
const file = process.env.SUPER_PLANER_DB ?? path.join(process.cwd(), '..', '.data', 'super-planer.db');
const g = globalThis as unknown as { __spdb?: DatabaseSync };

export function db(): DatabaseSync {
  if (!g.__spdb) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const d = new DatabaseSync(file);
    d.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 3000; PRAGMA foreign_keys = ON;');
    g.__spdb = d;
  }
  return g.__spdb;
}

export function tableExists(name: string): boolean {
  return !!db().prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name);
}
import Anthropic from '@anthropic-ai/sdk';
import { execFile } from 'node:child_process';

// Provider order: ANTHROPIC_API_KEY → local `claude` CLI (uses the logged-in Claude Code) → deterministic mock.
// Force one with LLM_PROVIDER=anthropic|claude-cli|mock.
export type Provider = 'anthropic' | 'claude-cli' | 'mock';

export function provider(): Provider {
  const forced = process.env.LLM_PROVIDER as Provider | undefined;
  if (forced) return forced;
  if (process.env.ANTHROPIC_API_KEY) return 'anthropic';
  if (process.env.LLM_DISABLE_CLI !== '1') return 'claude-cli';
  return 'mock';
}

function extractJSON(text: string): unknown {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body = fenced ? fenced[1] : text;
  const start = body.search(/[[{]/);
  if (start < 0) throw new Error('no JSON in model output');
  const end = Math.max(body.lastIndexOf('}'), body.lastIndexOf(']'));
  return JSON.parse(body.slice(start, end + 1));
}

async function viaAnthropic(system: string, user: string): Promise<string> {
  const client = new Anthropic();
