c.run('k2','w3','코어 루프','d','frozen','등불을 켜고 지하 정원 탐험 → 씨앗과 재료 모으기 → 등불이 꺼지기 전 귀환 → 오두막 정원에 심기 → 수확물로 도구 해금 → 다시 탐험.',380,0,t);
d.prepare('insert into wf_messages values (?,?,?,?,?)').run('q1','k1','agent','- https://picsum.photos/id/106/800/500',t);
"
IDS=$(curl -s -XPOST localhost:3103/api/import -H 'content-type: application/json' -d '{"workflow":"w3"}' | node -e "let s='';process.stdin.on('data',c=>s+=c).on('end',()=>{const b=JSON.parse(s);const inp=b.inputs.filter(i=>b.ids.includes(i.id));process.stdout.write(JSON.stringify({decisionIds:inp.filter(i=>i.kind==='decision').map(i=>i.id),imageIds:inp.filter(i=>i.kind==='image').map(i=>i.id)}))})")
echo $IDS; curl -s -XPOST localhost:3103/api/generate -H 'content-type: application/json' -d "$IDS" | node -e "let s='';process.stdin.on('data',c=>s+=c).on('end',()=>{console.log(JSON.parse(s).doc.markdown)})"

